def common_prefix(words: list[str]) -> str:
    if not words:
        return ''

    # Start with the first word as the initial prefix
    prefix = words[0]

    for word in words[1:]:
        # Shorten the prefix until it matches the beginning of the current word
        while not word.startswith(prefix):
            prefix = prefix[:-1]
            if not prefix:
                return ''

    return prefix
