def count_islands(grid: list[str]) -> int:
    if not grid or not grid[0]:
        return 0

    rows = len(grid)
    cols = len(grid[0])

    # Convert to a mutable 2D list for easier modification
    grid_list = [list(row) for row in grid]

    def dfs(r: int, c: int):
        if r < 0 or r >= rows or c < 0 or c >= cols:
            return
        if grid_list[r][c] != '1':
            return
        grid_list[r][c] = '0'  # Mark as visited
        dfs(r + 1, c)
        dfs(r - 1, c)
        dfs(r, c + 1)
        dfs(r, c - 1)

    count = 0
    for i in range(rows):
        for j in range(cols):
            if grid_list[i][j] == '1':
                count += 1
                dfs(i, j)

    return count
```

