def caesar(s: str, k: int) -> str:
    result = []
    for char in s:
        if char.isalpha():
            if char.isupper():
                base = ord('A')
            else:
                base = ord('a')
            # Normalize k to be in range [0, 26)
            shifted = (ord(char) - base + k) % 26
            result.append(chr(base + shifted))
        else:
            result.append(char)
    return ''.join(result)
